"""``pgkyl`` command-line entry point -- a chained pipeline on pure Click.

The chained syntax mirrors the fluent script API 1:1::

    pg.load('f.gkyl').interpolate().select(z0=0).plot()      # script
    pgkyl   f.gkyl    interpolate select --z0 0 plot   # CLI

Chaining and callback-before-dispatch are native to ``click.Group(chain=True)``,
so the only custom code is a small :class:`PgkylGroup.get_command` override for
command-name abbreviation and treating a bare filename as an implicit ``load``.
Every subcommand is compiled from a public API callable at import time. This
module owns only chaining, command aliases, and bare-file dispatch; it
contains no per-command option or execution definitions.
"""

from __future__ import annotations

from glob import glob
from types import MappingProxyType

import click

from postgkyl import __version__, version_report
from postgkyl.cli.compiler import (
    build_click_command,
    compile_public_surface,
    group_by_section,
)
from postgkyl.cli.discovery import discover_public_surface
from postgkyl.cli.state import DataSpace

# Compilation validates the complete discovered surface before registration.
# These aliases add spellings only; they never replace a generated command or
# alter its options.
MODELS = compile_public_surface(discover_public_surface())
COMMANDS = tuple(build_click_command(model) for model in MODELS)
COMMAND_SECTIONS = group_by_section(MODELS)
COMMAND_ALIASES = MappingProxyType({"pl": "plot", "ev": "evaluate"})


class PgkylGroup(click.Group):
  """Click's chained group with spelling-only command aliases."""

  def get_command(self, ctx, name):
    cmd = super().get_command(ctx, name)
    if cmd is not None:
      return cmd
    if name in COMMAND_ALIASES:
      target = COMMAND_ALIASES[name]
      command = super().get_command(ctx, target)
      if command is not None:
        return command
    matches = [c for c in self.list_commands(ctx) if c.startswith(name)]
    if len(matches) == 1:
      return super().get_command(ctx, matches[0])
    if matches:
      ctx.fail(f"Ambiguous command '{name}': {', '.join(sorted(matches))}")
    return None

  def resolve_command(self, ctx, args):
    """Expand a bare file pattern to the canonical ``load --file_name`` form."""
    if args:
      token = args[0]
      exact = click.Group.get_command(self, ctx, token)
      alias = COMMAND_ALIASES.get(token)
      if exact is None and alias is None and glob(token):
        args[:1] = ["load", "--file_name", token]
    return super().resolve_command(ctx, args)

  def format_commands(self, ctx, formatter) -> None:
    """Group ``pgkyl --help``'s command listing under section headers.

    Presentation only (see ``commands/__init__.py``'s ``COMMAND_SECTIONS``
    and "14-cli.md"'s "Help output organization"): every command stays a
    flat, chainable top-level ``click.Command`` resolved exactly as before;
    only how they are *printed* changes, mirroring how ``git``/``docker``
    group their subcommand help.
    """
    for section, names in COMMAND_SECTIONS.items():
      rows = []
      for name in names:
        cmd = self.get_command(ctx, name)
        if cmd is None:
          continue
        rows.append((name, cmd.get_short_help_str(limit=formatter.width - 6)))
      if rows:
        with formatter.section(section):
          formatter.write_dl(rows)


def _print_version(ctx, param, value) -> None:
  if not value or ctx.resilient_parsing:
    return
  click.echo(version_report(__version__))
  ctx.exit()


@click.group(cls=PgkylGroup,
             chain=True,
             context_settings=dict(help_option_names=["-h", "--help"]))
@click.option("--version",
              is_flag=True,
              expose_value=False,
              is_eager=True,
              callback=_print_version,
              help="Show version, commit, Gkeyll build info, and exit.")
@click.pass_context
def cli(ctx) -> None:
  """Postprocessing and plotting tool for Gkeyll data.

  Datasets are loaded, processed and plotted by chaining commands, e.g.::

      pgkyl file.gkyl interpolate select --z0 0 plot
  """
  ctx.obj = DataSpace()


for _command in COMMANDS:
  cli.add_command(_command)

__all__ = [
    "COMMANDS",
    "COMMAND_ALIASES",
    "COMMAND_SECTIONS",
    "MODELS",
    "PgkylGroup",
    "cli",
]

if __name__ == "__main__":
  cli()
"""Deterministic discovery of command metadata from public API roots."""

from __future__ import annotations

from dataclasses import dataclass
import inspect
from types import ModuleType

import postgkyl
from postgkyl.cli_spec import command_spec, hidden_spec


class SurfaceClassificationError(ValueError):
  """A public CLI candidate is neither exposed nor explicitly hidden."""


@dataclass(frozen=True)
class DiscoveredCallable:
  name: str
  callable: object
  public_path: str


def _classify(obj, path: str) -> bool:
  exposed = command_spec(obj) is not None
  excluded = hidden_spec(obj) is not None
  if exposed == excluded:
    state = "both exposed and hidden" if exposed else "unclassified"
    raise SurfaceClassificationError(f"{path}: public callable is {state}")
  return exposed


def _functions(module: ModuleType):
  public = getattr(module, "__all__", None)
  names = public if public is not None else sorted(
      name for name, value in vars(module).items() if not name.startswith("_")
      and inspect.isfunction(value) and value.__module__ == module.__name__)
  for name in names:
    value = getattr(module, name)
    if inspect.isfunction(value):
      yield name, value


def _diagnostic_modules(root: ModuleType):
  seen: set[int] = set()

  def visit(module):
    if id(module) in seen:
      return
    seen.add(id(module))
    yield module
    for name in getattr(module, "__all__", ()):
      value = getattr(module, name)
      if isinstance(
          value,
          ModuleType) and value.__name__.startswith("postgkyl.diagnostics"):
        yield from visit(value)

  yield from visit(root)


def discover_public_surface(facade=postgkyl) -> tuple[DiscoveredCallable, ...]:
  """Walk the declared public roots and return all exposed callables."""
  found: list[DiscoveredCallable] = []
  classified: set[tuple[int, str]] = set()

  def consider(obj, path: str, name: str) -> None:
    key = (id(obj), name)
    if key in classified:
      return
    classified.add(key)
    if _classify(obj, path):
      found.append(DiscoveredCallable(name, obj, path))

  # Fluent methods are the authoritative inventory of per-dataset commands.
  for cls_name in ("GData", "GDataGroup"):
    cls = getattr(facade, cls_name)
    for name, value in sorted(cls.__dict__.items()):
      if name.startswith("_") or not callable(value):
        continue
      consider(value, f"{cls.__module__}.{cls.__qualname__}.{name}", name)

  # Public facade functions not already reached through their fluent view.
  for name in facade.__all__:
    value = getattr(facade, name)
    if inspect.isfunction(value):
      path = f"postgkyl.{name}"
      if value.__module__.startswith("postgkyl.diagnostics"):
        _classify(value, path)
      else:
        consider(value, path, name)

  diagnostics = facade.diagnostics
  for module in _diagnostic_modules(diagnostics):
    if module is diagnostics:
      continue
    relative = module.__name__.removeprefix("postgkyl.diagnostics.")
    # Model-family packages group related diagnostic modules without erasing
    # each module's public command vocabulary. For example,
    # diagnostics.mom.five_moment.pressure becomes ``five_moment_pressure``
    # and cannot collide with ten_moment.pressure.
    namespace = relative.rsplit(".", 1)[-1]
    for name, value in _functions(module):
      if not value.__module__.startswith("postgkyl.diagnostics"):
        # Lower-layer re-exports retain their canonical command vocabulary.
        _classify(value, f"{module.__name__}.{name}")
        continue
      consider(value, f"{module.__name__}.{name}", f"{namespace}_{name}")

    # Registry values are public vocabulary roots too. Identity de-duplication
    # means aliases do not invent additional command names.
    variables = getattr(module, "VARIABLES", None)
    if isinstance(variables, dict):
      for value in variables.values():
        if inspect.isfunction(value):
          consider(value, f"{module.__name__}.VARIABLES[{value.__name__!r}]",
                   f"{namespace}_{value.__name__}")

  # A fluent view and facade function may be aliases of the same operation.
  # Keep one deterministic view.
  unique: dict[tuple[str, int], DiscoveredCallable] = {}
  for item in found:
    key = (item.name, id(item.callable))
    unique.setdefault(key, item)
  return tuple(
      sorted(unique.values(), key=lambda item: (item.name, item.public_path)))


__all__ = [
    "DiscoveredCallable", "SurfaceClassificationError",
    "discover_public_surface"
]
"""Frozen, dependency-free records describing the generated CLI surface.

This package deliberately knows nothing about Click or postgkyl datasets.
API-owning modules attach these records to their public callables; the CLI is
the only layer that interprets them.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum, auto
from typing import Callable


class Section(Enum):
  """Top-level help sections, in display order."""

  VERBS = "Verbs"
  DIAGNOSTICS = "Diagnostics"
  RENDER = "Render"
  UTILITY = "Utility"


class Execution(Enum):
  """Closed set of working-set adapters used by the CLI runtime."""

  MAP_REPLACE = auto()
  MAP_APPEND = auto()
  MAP_OR_TERMINAL_EACH = auto()
  COMBINE = auto()
  TERMINAL_EACH = auto()
  TERMINAL_ALL = auto()
  LOAD = auto()


class ResultPolicy(Enum):
  """How a returned API value is presented at the command-line edge."""

  DATA = auto()
  VALUE = auto()
  SILENT = auto()


@dataclass(frozen=True)
class CommandSpec:
  """Pipeline metadata attached to one canonical API callable."""

  section: Section
  execution: Execution
  consumes_inputs: bool = False
  result: ResultPolicy = ResultPolicy.DATA
  order: int = 0

  def __post_init__(self) -> None:
    if not isinstance(self.section, Section) or not isinstance(
        self.execution, Execution) or not isinstance(self.result, ResultPolicy):
      raise TypeError(
          "CommandSpec section, execution, and result must be enums")
    if not isinstance(self.consumes_inputs, bool):
      raise TypeError("CommandSpec consumes_inputs must be a bool value")
    if not isinstance(self.order, int) or isinstance(self.order, bool):
      raise TypeError("CommandSpec order must be an integer")
    if self.execution is Execution.LOAD:
      if self.consumes_inputs:
        raise ValueError("LOAD commands cannot consume working-set inputs")
    if self.consumes_inputs and self.execution not in (Execution.MAP_APPEND,
                                                       Execution.COMBINE):
      raise ValueError(
          "only MAP_APPEND and COMBINE commands may consume their inputs")
    if self.execution in (Execution.TERMINAL_EACH, Execution.TERMINAL_ALL):
      if self.consumes_inputs:
        raise ValueError("terminal commands cannot consume working-set inputs")
      if self.result is ResultPolicy.DATA:
        raise ValueError("terminal commands need a non-DATA result policy")


@dataclass(frozen=True)
class DatasetRef:
  """Resolve this API dataset parameter from a unique working-set tag."""

  default_tag: str | None = None

  def __post_init__(self) -> None:
    if self.default_tag is not None and not self.default_tag:
      raise ValueError("DatasetRef default_tag must be non-empty when supplied")


@dataclass(frozen=True)
class PipelineInput:
  """Inject this parameter from the selected CLI working set."""


@dataclass(frozen=True)
class CliType:
  """Lossless CLI input type for a broader direct-Python annotation."""

  annotation: object


@dataclass(frozen=True)
class CliArgument:
  """Expose this API parameter as a positional command-line argument."""


@dataclass(frozen=True)
class ChoiceProvider:
  """Obtain an option's choices from the API registry returned by provider."""

  provider: Callable[[], object]

  def __post_init__(self) -> None:
    if not callable(self.provider):
      raise TypeError("ChoiceProvider requires a callable provider")


@dataclass(frozen=True)
class KeyValue:
  """Parse a mapping as repeated ``key=value`` option values."""


@dataclass(frozen=True)
class CliHidden:
  """Exclude a callable, or an optional keyword parameter, from the CLI.

  As an Annotated parameter marker, the Python default is used unchanged.
  """

  reason: str

  def __post_init__(self) -> None:
    if not self.reason.strip():
      raise ValueError("CliHidden requires a non-empty reason")


_COMMAND_ATTR = "__postgkyl_command_spec__"
_HIDDEN_ATTR = "__postgkyl_cli_hidden__"


def command(spec: CommandSpec):
  """Attach ``spec`` to a callable without wrapping or registering it."""
  if not isinstance(spec, CommandSpec):
    raise TypeError("command() requires a CommandSpec")

  def decorate(fn):
    if hasattr(fn, _HIDDEN_ATTR):
      raise ValueError(f"{fn!r} is already marked CliHidden")
    previous = getattr(fn, _COMMAND_ATTR, None)
    if previous is not None and previous != spec:
      raise ValueError(f"{fn!r} already has a different CommandSpec")
    setattr(fn, _COMMAND_ATTR, spec)
    return fn

  return decorate


def hidden(reason: str):
  """Explicitly mark a public callable as unavailable from the CLI."""
  marker = CliHidden(reason)

  def decorate(fn):
    if hasattr(fn, _COMMAND_ATTR):
      raise ValueError(f"{fn!r} already has a CommandSpec")
    setattr(fn, _HIDDEN_ATTR, marker)
    return fn

  return decorate


def command_spec(fn) -> CommandSpec | None:
  """Return the immutable command metadata attached to ``fn``."""
  return getattr(fn, _COMMAND_ATTR, None)


def hidden_spec(fn) -> CliHidden | None:
  """Return the explicit CLI exclusion attached to ``fn``."""
  return getattr(fn, _HIDDEN_ATTR, None)


__all__ = [
    "ChoiceProvider",
    "CliArgument",
    "CliHidden",
    "CliType",
    "CommandSpec",
    "DatasetRef",
    "Execution",
    "KeyValue",
    "PipelineInput",
    "ResultPolicy",
    "Section",
    "command",
    "command_spec",
    "hidden",
    "hidden_spec",
]

