from .docstrings import parse_docstring


class CommandCompilationError(ValueError):
  """A public callable cannot be represented by the closed CLI contract."""


class CodecKind(Enum):
  STRING = "string"
  INTEGER = "integer"
  FLOAT = "float"
  BOOLEAN = "boolean"
  PATH = "path"
  CHOICE = "choice"
  ENUM = "enum"
  SEQUENCE = "sequence"
  TUPLE = "tuple"
  MAPPING = "mapping"


@dataclass(frozen=True)
class TypeCodec:
  kind: CodecKind
  python_type: object
  optional: bool = False
  choices: tuple[object, ...] = ()
  items: tuple["TypeCodec", ...] = ()
  multiple: bool = False
  nargs: int = 1


@dataclass(frozen=True)
class ParameterModel:
  name: str
  kind: inspect._ParameterKind
  annotation: object
  codec: TypeCodec | None
  help: str | None
  required: bool
  default: object
  injected: bool = False
  dataset_ref: bool = False
  argument: bool = False


